/* ==========================================================================
   長さ単位変換ツール (Length Unit Converter)
   デザインシステム & スタイルシート
   ========================================================================== */

:root {
  --font-sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, "Noto Sans JP", sans-serif;
  --font-mono: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace;

  /* カラーパレット */
  --color-primary: #2563eb;
  --color-primary-hover: #1d4ed8;
  --color-primary-light: #eff6ff;
  --color-primary-border: #bfdbfe;
  --color-accent: #0ea5e9;
  --color-success: #10b981;
  --color-success-light: #ecfdf5;

  /* ニュートラルカラー */
  --bg-page: #f8fafc;
  --bg-card: #ffffff;
  --bg-subtle: #f1f5f9;
  --border-color: #e2e8f0;
  --border-focus: #3b82f6;
  --text-main: #0f172a;
  --text-muted: #64748b;
  --text-light: #94a3b8;

  /* シャドウ & 角丸 */
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --radius-full: 9999px;
  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.07), 0 2px 4px -2px rgba(0, 0, 0, 0.05);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.08), 0 4px 6px -4px rgba(0, 0, 0, 0.04);
  --shadow-active: 0 0 0 2px rgba(37, 99, 235, 0.2);

  /* トランジション */
  --transition-fast: 0.15s ease;
  --transition-normal: 0.25s ease;
}

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-sans);
  background-color: var(--bg-page);
  color: var(--text-main);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

button, input, select {
  font-family: inherit;
}

/* ==========================================================================
   レイアウト基本構成
   ========================================================================== */

.converter-app {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  background: linear-gradient(180deg, #f0f7ff 0%, var(--bg-page) 280px);
}

.app-header {
  padding: 2.5rem 1.25rem 1.5rem;
  text-align: center;
}

.app-title {
  font-size: 1.85rem;
  font-weight: 800;
  color: #1e293b;
  letter-spacing: -0.025em;
  margin-bottom: 0.5rem;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
}

.app-subtitle {
  font-size: 0.95rem;
  color: var(--text-muted);
  max-width: 540px;
  margin: 0 auto;
}

.main-container {
  width: 100%;
  max-width: 900px;
  margin: 0 auto;
  padding: 0 1rem 3rem;
  display: flex;
  flex-direction: column;
  gap: 1.75rem;
}

/* ==========================================================================
   入力セクション (.input-section, .input-card, etc.)
   ========================================================================== */

.input-section {
  width: 100%;
}

.input-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 1.5rem;
  box-shadow: var(--shadow-md);
}

.input-group {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.input-label {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--text-muted);
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.input-row {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  width: 100%;
}

.number-input {
  flex: 1;
  min-width: 0;
  height: 3.25rem;
  padding: 0 1rem;
  font-size: 1.35rem;
  font-family: var(--font-mono);
  font-weight: 600;
  color: var(--text-main);
  background-color: var(--bg-card);
  border: 2px solid var(--border-color);
  border-radius: var(--radius-md);
  outline: none;
  transition: border-color var(--transition-fast), box-shadow var(--transition-fast);
}

.number-input:focus {
  border-color: var(--border-focus);
  box-shadow: var(--shadow-active);
}

.number-input::placeholder {
  color: var(--text-light);
  font-weight: 400;
}

.unit-select {
  height: 3.25rem;
  min-width: 130px;
  padding: 0 1rem;
  font-size: 1rem;
  font-weight: 600;
  color: #1e3a8a;
  background-color: var(--color-primary-light);
  border: 2px solid var(--color-primary-border);
  border-radius: var(--radius-md);
  outline: none;
  cursor: pointer;
  transition: all var(--transition-fast);
}

.unit-select:hover {
  background-color: #dbeafe;
}

.unit-select:focus {
  border-color: var(--border-focus);
  box-shadow: var(--shadow-active);
}

.clear-btn {
  height: 3.25rem;
  width: 3.25rem;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  background-color: var(--bg-subtle);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  color: var(--text-muted);
  cursor: pointer;
  font-size: 1.1rem;
  transition: all var(--transition-fast);
}

.clear-btn:hover {
  background-color: #fee2e2;
  color: #ef4444;
  border-color: #fca5a5;
}

/* ==========================================================================
   クイックプリセットセクション (.presets-section)
   ========================================================================== */

.presets-section {
  margin-top: 1.25rem;
  padding-top: 1.25rem;
  border-top: 1px dashed var(--border-color);
}

.presets-title {
  font-size: 0.8rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--text-light);
  margin-bottom: 0.65rem;
}

.preset-list {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
}

.preset-btn {
  padding: 0.4rem 0.85rem;
  font-size: 0.825rem;
  font-weight: 500;
  color: #334155;
  background-color: var(--bg-subtle);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-full);
  cursor: pointer;
  white-space: nowrap;
  transition: all var(--transition-fast);
}

.preset-btn:hover {
  background-color: var(--color-primary-light);
  color: var(--color-primary);
  border-color: var(--color-primary-border);
  transform: translateY(-1px);
}

.preset-btn:active {
  transform: translateY(0);
}

/* ==========================================================================
   換算結果グリッド (.results-section, .unit-card, etc.)
   ========================================================================== */

.results-section {
  width: 100%;
}

.results-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 0.75rem;
}

.results-title {
  font-size: 1.1rem;
  font-weight: 700;
  color: var(--text-main);
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.results-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: 0.85rem;
}

.unit-card {
  position: relative;
  background: var(--bg-card);
  border: 1.5px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 1rem 1.15rem;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  gap: 0.75rem;
  transition: transform var(--transition-fast), border-color var(--transition-fast), box-shadow var(--transition-fast);
  cursor: pointer;
}

.unit-card:hover {
  border-color: #cbd5e1;
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

.unit-card-active {
  border-color: var(--color-primary);
  background: linear-gradient(180deg, #f8faff 0%, #ffffff 100%);
  box-shadow: 0 0 0 1px var(--color-primary), var(--shadow-sm);
}

.unit-card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.unit-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-mono);
  font-size: 0.85rem;
  font-weight: 700;
  padding: 0.2rem 0.55rem;
  background-color: var(--bg-subtle);
  color: #334155;
  border-radius: var(--radius-sm);
}

.unit-card-active .unit-badge {
  background-color: var(--color-primary);
  color: #ffffff;
}

.unit-full-name {
  font-size: 0.825rem;
  font-weight: 500;
  color: var(--text-muted);
}

.unit-value-row {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 0.5rem;
}

.unit-value {
  font-family: var(--font-mono);
  font-size: 1.35rem;
  font-weight: 700;
  color: var(--text-main);
  word-break: break-all;
  line-height: 1.25;
}

.copy-btn {
  position: relative;
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 2.25rem;
  height: 2.25rem;
  background-color: var(--bg-subtle);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  color: var(--text-muted);
  cursor: pointer;
  transition: all var(--transition-fast);
}

.copy-btn:hover {
  background-color: var(--color-primary-light);
  color: var(--color-primary);
  border-color: var(--color-primary-border);
}

.copied-tooltip {
  position: absolute;
  top: -2rem;
  right: 50%;
  transform: translateX(50%);
  background-color: #1e293b;
  color: #ffffff;
  font-size: 0.72rem;
  font-weight: 600;
  padding: 0.25rem 0.5rem;
  border-radius: var(--radius-sm);
  white-space: nowrap;
  pointer-events: none;
  animation: fadeInOut 1.5s ease-in-out;
  box-shadow: var(--shadow-sm);
  z-index: 10;
}

@keyframes fadeInOut {
  0% { opacity: 0; transform: translate(50%, 4px); }
  15% { opacity: 1; transform: translate(50%, 0); }
  85% { opacity: 1; transform: translate(50%, 0); }
  100% { opacity: 0; transform: translate(50%, -4px); }
}

/* ==========================================================================
   視覚的比較セクション (.comparison-section, etc.)
   ========================================================================== */

.comparison-section {
  width: 100%;
}

.comparison-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 1.35rem 1.5rem;
  box-shadow: var(--shadow-sm);
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.comparison-title {
  font-size: 1.05rem;
  font-weight: 700;
  color: var(--text-main);
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.comparison-item {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
}

.comparison-label {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 0.85rem;
  font-weight: 600;
  color: #334155;
}

.comparison-subtext {
  color: var(--text-light);
  font-weight: 400;
}

.comparison-progress-bg {
  width: 100%;
  height: 0.75rem;
  background-color: var(--bg-subtle);
  border-radius: var(--radius-full);
  overflow: hidden;
}

.comparison-progress-fill {
  height: 100%;
  border-radius: var(--radius-full);
  background: linear-gradient(90deg, #38bdf8 0%, #2563eb 100%);
  transition: width 0.35s ease-out;
}

/* ==========================================================================
   基準・早見表セクション (.reference-section, .reference-table)
   ========================================================================== */

.reference-section {
  width: 100%;
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 1.35rem 1.5rem;
  box-shadow: var(--shadow-sm);
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
}

.reference-table-wrapper {
  width: 100%;
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
}

.reference-table {
  width: 100%;
  min-width: 480px;
  border-collapse: separate;
  border-spacing: 0;
  font-size: 0.875rem;
  margin-top: 0.75rem;
}

.reference-table th,
.reference-table td {
  padding: 0.75rem 0.85rem;
  text-align: left;
  border-bottom: 1px solid var(--border-color);
}

.reference-table th {
  font-weight: 700;
  color: var(--text-muted);
  background-color: var(--bg-subtle);
}

.reference-table th:first-child {
  border-top-left-radius: var(--radius-sm);
}

.reference-table th:last-child {
  border-top-right-radius: var(--radius-sm);
}

.reference-table tr:last-child td {
  border-bottom: none;
}

.reference-table tr:hover td {
  background-color: #fafbfc;
}

/* ==========================================================================
   フッター (.footer)
   ========================================================================== */

.footer {
  margin-top: auto;
  padding: 1.5rem 1rem;
  text-align: center;
  font-size: 0.825rem;
  color: var(--text-light);
  border-top: 1px solid var(--border-color);
  background-color: #ffffff;
}

/* ==========================================================================
   レスポンシブ対応（幅360px〜タブレット）
   ========================================================================== */

@media (max-width: 640px) {
  .app-header {
    padding: 1.75rem 1rem 1rem;
  }

  .app-title {
    font-size: 1.45rem;
  }

  .app-subtitle {
    font-size: 0.85rem;
  }

  .input-card {
    padding: 1rem;
  }

  .input-row {
    flex-wrap: wrap;
  }

  .number-input {
    width: 100%;
    order: 1;
    font-size: 1.2rem;
    height: 3rem;
  }

  .unit-select {
    flex: 1;
    order: 2;
    min-width: 0;
    height: 2.75rem;
    font-size: 0.925rem;
  }

  .clear-btn {
    order: 3;
    height: 2.75rem;
    width: 2.75rem;
  }

  .results-grid {
    grid-template-columns: 1fr;
    gap: 0.65rem;
  }

  .unit-card {
    padding: 0.85rem 1rem;
  }

  .unit-value {
    font-size: 1.2rem;
  }

  .reference-table {
    font-size: 0.775rem;
  }

  .reference-table th,
  .reference-table td {
    padding: 0.55rem 0.5rem;
  }
}

export type UnitSystem = 'metric' | 'imperial';

export type UnitId = 'mm' | 'cm' | 'm' | 'km' | 'in' | 'ft' | 'yd' | 'mi';

export interface LengthUnitInfo {
  id: UnitId;
  name: string;
  symbol: string;
  toMeters: number;
  description: string;
  system: UnitSystem;
}

export interface ConversionResult {
  unit: LengthUnitInfo;
  value: number;
  formatted: string;
  isActive?: boolean;
}

export interface PresetItem {
  label: string;
  value: number;
  unitId: UnitId;
}

export interface ComparisonBenchmark {
  id: string;
  name: string;
  meters: number;
  description: string;
  category: 'micro' | 'everyday' | 'large';
  icon?: string;
}

import { COMPARISON_BENCHMARKS } from '../constants';

interface VisualComparisonProps {
  currentMeters?: number;
}

const VisualComparison = ({ currentMeters = 0 }: VisualComparisonProps) => {
  const isPositive = typeof currentMeters === 'number' && currentMeters > 0;

  return (
    <section className="comparison-section">
      <div className="comparison-card">
        <h3 className="comparison-title">
          <span>📏 身近なモノとの長さ比較</span>
        </h3>

        {COMPARISON_BENCHMARKS.map((benchmark) => {
          const ratio = isPositive ? currentMeters / benchmark.meters : 0;
          const percentage = isPositive
            ? Math.min(100, Math.max(0, ratio * 100))
            : 0;

          let comparisonText = '-';
          if (isPositive) {
            if (ratio >= 100) {
              comparisonText = `約 ${Math.round(ratio).toLocaleString('ja-JP')} 倍`;
            } else if (ratio >= 1) {
              comparisonText = `約 ${ratio.toFixed(1)} 倍`;
            } else if (ratio >= 0.01) {
              comparisonText = `約 ${(ratio * 100).toFixed(1)} %`;
            } else {
              comparisonText = `約 ${(ratio * 100).toFixed(3)} %`;
            }
          }

          return (
            <div key={benchmark.id} className="comparison-item">
              <div className="comparison-label">
                <span>
                  {benchmark.icon && `${benchmark.icon} `}
                  {benchmark.name}
                  <span className="comparison-subtext"> ({benchmark.description})</span>
                </span>
                <span>{comparisonText}</span>
              </div>
              <div
                className="comparison-progress-bg"
                role="progressbar"
                aria-valuenow={Math.round(percentage)}
                aria-valuemin={0}
                aria-valuemax={100}
                aria-label={`${benchmark.name}に対する割合`}
              >
                <div
                  className="comparison-progress-fill"
                  style={{ width: `${percentage}%` }}
                />
              </div>
            </div>
          );
        })}
      </div>
    </section>
  );
};

export default VisualComparison;

import { useState, useCallback } from 'react';
import { ConversionResult, UnitId } from '../types';

interface UnitConverterCardProps {
  results?: ConversionResult[];
  activeUnitId: UnitId;
  onSelectUnit?: (id: UnitId) => void;
}

const UnitConverterCard = ({
  results = [],
  activeUnitId,
  onSelectUnit,
}: UnitConverterCardProps) => {
  const [copiedUnitId, setCopiedUnitId] = useState<UnitId | null>(null);

  const fallbackCopyText = (text: string, unitId: UnitId) => {
    try {
      const textArea = document.createElement('textarea');
      textArea.value = text;
      textArea.style.position = 'fixed';
      textArea.style.opacity = '0';
      document.body.appendChild(textArea);
      textArea.focus();
      textArea.select();
      const successful = document.execCommand('copy');
      document.body.removeChild(textArea);
      if (successful) {
        setCopiedUnitId(unitId);
        setTimeout(() => {
          setCopiedUnitId(null);
        }, 1500);
      }
    } catch (err) {
      console.error('フォールバックコピーに失敗しました:', err);
    }
  };

  const handleCopy = useCallback(
    (e: React.MouseEvent, item: ConversionResult) => {
      e.stopPropagation();
      const textToCopy = `${item.formatted} ${item.unit.symbol}`;

      if (navigator.clipboard && typeof navigator.clipboard.writeText === 'function') {
        navigator.clipboard
          .writeText(textToCopy)
          .then(() => {
            setCopiedUnitId(item.unit.id);
            setTimeout(() => {
              setCopiedUnitId(null);
            }, 1500);
          })
          .catch((err) => {
            console.warn('クリップボードAPIの書き込みに失敗したためフォールバックを実行します:', err);
            fallbackCopyText(textToCopy, item.unit.id);
          });
      } else {
        fallbackCopyText(textToCopy, item.unit.id);
      }
    },
    []
  );

  return (
    <div className="results-section">
      <div className="results-header">
        <h2 className="results-title">
          <span>🔄 変換結果一覧</span>
        </h2>
      </div>

      <div className="results-grid">
        {results.map((item) => {
          const isActive = item.unit.id === activeUnitId;
          const cardClass = isActive ? 'unit-card unit-card-active' : 'unit-card';
          const isCopied = copiedUnitId === item.unit.id;

          return (
            <div
              key={item.unit.id}
              className={cardClass}
              onClick={() => onSelectUnit?.(item.unit.id)}
            >
              <div
                className="unit-card-header"
                role="button"
                tabIndex={0}
                aria-pressed={isActive}
                aria-label={`${item.unit.name}を基準単位に設定`}
                onKeyDown={(e) => {
                  if (e.key === 'Enter' || e.key === ' ') {
                    e.preventDefault();
                    onSelectUnit?.(item.unit.id);
                  }
                }}
              >
                <span className="unit-badge">{item.unit.symbol}</span>
                <span className="unit-full-name">{item.unit.name}</span>
              </div>

              <div className="unit-value-row">
                <span className="unit-value">{item.formatted}</span>

                <button
                  type="button"
                  className="copy-btn"
                  title={`${item.unit.name}の数値をコピー`}
                  aria-label={`${item.unit.name}の数値をコピー`}
                  onClick={(e) => handleCopy(e, item)}
                >
                  📋
                  {isCopied && <span className="copied-tooltip">コピー完了!</span>}
                </button>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

export default UnitConverterCard;

import { useState, useMemo, useCallback } from 'react';
import { UnitId, ConversionResult } from './types';
import { LENGTH_UNITS, PRESET_ITEMS } from './constants';
import UnitConverterCard from './components/UnitConverterCard';
import VisualComparison from './components/VisualComparison';

// 数値のフォーマット補助関数
const formatLength = (val: number): string => {
  if (isNaN(val) || !isFinite(val)) return '0';
  if (val === 0) return '0';

  const absVal = Math.abs(val);

  // 極小・極大値は指数表記で早期リターン
  if (absVal < 0.000001 || absVal >= 100000000) {
    return val.toExponential(4);
  }

  // 小数第6位までに丸め、末尾の不要なゼロを削除
  const fixed = Number(val.toFixed(6));
  const fixedStr = fixed.toString();

  // 指数表記が含まれる場合はそのまま返却し、後続の桁区切り処理で破損するのを防ぐ
  if (fixedStr.includes('e') || fixedStr.includes('E')) {
    return fixedStr;
  }

  // 桁区切り処理
  const parts = fixedStr.split('.');
  parts[0] = Number(parts[0]).toLocaleString('ja-JP');
  return parts.join('.');
};

const App = () => {
  const [inputValue, setInputValue] = useState<string>('1');
  const [selectedUnitId, setSelectedUnitId] = useState<UnitId>('m');

  // 入力された値を数値に変換
  const parsedValue = useMemo(() => {
    const trimmed = inputValue.trim();
    if (trimmed === '' || trimmed === '.') return 0;
    const num = parseFloat(trimmed);
    return isNaN(num) ? 0 : num;
  }, [inputValue]);

  // 現在の入力値を「メートル」基準で算出
  const currentMeters = useMemo(() => {
    const currentUnit = LENGTH_UNITS.find((u) => u.id === selectedUnitId);
    if (!currentUnit) return 0;
    return parsedValue * currentUnit.toMeters;
  }, [parsedValue, selectedUnitId]);

  // 全単位に対する変換結果をリアルタイム生成
  const conversionResults: ConversionResult[] = useMemo(() => {
    return LENGTH_UNITS.map((unit) => {
      const convertedValue = currentMeters / unit.toMeters;
      return {
        unit,
        value: convertedValue,
        formatted: formatLength(convertedValue),
      };
    });
  }, [currentMeters]);

  // 入力値変更ハンドラ
  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = e.target.value;
    // 正の数値と小数点のみ許可
    if (/^[0-9]*\.?[0-9]*$/.test(val) || val === '') {
      setInputValue(val);
    }
  };

  // クリアボタン
  const handleClear = () => {
    setInputValue('');
  };

  // プリセット適用
  const handleApplyPreset = (value: number, unitId: UnitId) => {
    setInputValue(value.toString());
    setSelectedUnitId(unitId);
  };

  // カードクリックで基準単位切り替え
  const handleSelectUnit = useCallback(
    (newUnitId: UnitId) => {
      if (newUnitId === selectedUnitId) return;
      const targetUnit = LENGTH_UNITS.find((u) => u.id === newUnitId);
      if (!targetUnit) return;

      const converted = currentMeters / targetUnit.toMeters;
      setInputValue(formatLength(converted).replace(/,/g, ''));
      setSelectedUnitId(newUnitId);
    },
    [currentMeters, selectedUnitId]
  );

  return (
    <div className="converter-app">
      <header className="app-header">
        <h1 className="app-title">
          <span>📏</span> 長さ単位一括変換ツール
        </h1>
        <p className="app-subtitle">
          mm・cm・m・km・インチ・フィートをリアルタイム相互変換。ワンクリックでコピーや身近な長さとの比較が可能です。
        </p>
      </header>

      <main className="main-container">
        {/* 入力セクション */}
        <section className="input-section">
          <div className="input-card">
            <div className="input-group">
              <label htmlFor="length-input" className="input-label">
                <span>変換したい数値を入力</span>
                <span>基準単位を選択</span>
              </label>

              <div className="input-row">
                <input
                  id="length-input"
                  type="text"
                  inputMode="decimal"
                  className="number-input"
                  placeholder="例: 100"
                  value={inputValue}
                  onChange={handleInputChange}
                  autoComplete="off"
                />

                <select
                  aria-label="基準単位"
                  className="unit-select"
                  value={selectedUnitId}
                  onChange={(e) => setSelectedUnitId(e.target.value as UnitId)}
                >
                  {LENGTH_UNITS.map((u) => (
                    <option key={u.id} value={u.id}>
                      {u.symbol} ({u.name})
                    </option>
                  ))}
                </select>

                <button
                  type="button"
                  className="clear-btn"
                  title="入力をクリア"
                  aria-label="入力をクリア"
                  onClick={handleClear}
                >
                  ✕
                </button>
              </div>
            </div>

            {/* クイックプリセット */}
            <div className="presets-section">
              <div className="presets-title">よく使われる長さプリセット</div>
              <div className="preset-list">
                {PRESET_ITEMS.map((item, idx) => (
                  <button
                    key={idx}
                    type="button"
                    className="preset-btn"
                    onClick={() => handleApplyPreset(item.value, item.unitId)}
                  >
                    {item.label}
                  </button>
                ))}
              </div>
            </div>
          </div>
        </section>

        {/* 変換結果グリッド */}
        <UnitConverterCard
          results={conversionResults}
          activeUnitId={selectedUnitId}
          onSelectUnit={handleSelectUnit}
        />

        {/* 身近な物とのビジュアル比較 */}
        <VisualComparison currentMeters={currentMeters} />

        {/* 単位基準の早見表 */}
        <section className="reference-section">
          <h3 className="comparison-title">
            <span>📖 各単位の定義・換算基準表</span>
          </h3>
          <div className="reference-table-wrapper">
            <table className="reference-table">
              <thead>
                <tr>
                  <th>単位記号</th>
                  <th>単位名</th>
                  <th>メートル換算 (1単位あたり)</th>
                  <th>説明・定義</th>
                </tr>
              </thead>
              <tbody>
                {LENGTH_UNITS.map((u) => (
                  <tr key={u.id}>
                    <td>
                      <strong>{u.symbol}</strong>
                    </td>
                    <td>{u.name}</td>
                    <td>{u.toMeters} m</td>
                    <td>{u.description}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </section>
      </main>

      <footer className="footer">
        長さ単位相互変換ツール (mm, cm, m, km, inch, ft) &copy; {new Date().getFullYear()}
      </footer>
    </div>
  );
};

export default App;
